#define MAX_STEPS 100
#define INTERSECT_SIZE 0.01

vec2 rotate2d(vec2 v, float a) {
	float sinA = sin(a);
	float cosA = cos(a);
	return vec2(v.x * cosA - v.y * sinA, v.y * cosA + v.x * sinA);	
}

// SDFs
float torus(vec3 p, vec2 t) {
    vec2 q = vec2(length(p.xy) - t.x, p.z);
    return length(q) - t.y;
}

float isInsideTorus(vec3 p, vec2 t) {
    vec2 q = vec2(length(p.xy) - t.x, p.z);
    return length(q); // < t.y;
}

float point(vec3 rayPos, vec3 point)
{
    return distance(rayPos, point);
}

vec4 blendColors(vec4 color1, vec4 color2) {
    float A1 = color1.a;
    float A2 = color2.a;

    // Calculate blended alpha
    float Ar = A2 + A1 * (1.0 - A2);

    // Calculate blended color
    vec3 Cr = (color2.rgb * A2 + color1.rgb * A1 * (1.0 - A2)) / max(Ar, 1e-6);

    return vec4(Cr, Ar);
}

vec3 hsv2rgb(vec3 hsv) {
    float C = hsv.z * hsv.y; // Chroma
    float X = C * (1.0 - abs(mod(hsv.x * 6.0, 2.0) - 1.0));
    float m = hsv.z - C;

    vec3 rgb;
    if (hsv.x < 1.0 / 6.0)      rgb = vec3(C, X, 0.0);
    else if (hsv.x < 2.0 / 6.0) rgb = vec3(X, C, 0.0);
    else if (hsv.x < 3.0 / 6.0) rgb = vec3(0.0, C, X);
    else if (hsv.x < 4.0 / 6.0) rgb = vec3(0.0, X, C);
    else if (hsv.x < 5.0 / 6.0) rgb = vec3(X, 0.0, C);
    else                        rgb = vec3(C, 0.0, X);

    return rgb + m;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 screenPos = (fragCoord.xy / iResolution.xy) * 2.0 - 1.0;
	vec3 cameraDir = vec3(0.0, 0.0, 0.8);
	vec3 cameraPlaneU = vec3(1.0, 0.0, 0.0);
	vec3 cameraPlaneV = vec3(0.0, 1.0, 0.0) * iResolution.y / iResolution.x;
	vec3 rayDir = normalize(cameraDir + screenPos.x * cameraPlaneU + screenPos.y * cameraPlaneV);

    float rotate_size = 10.0;

	vec3 rayPos = vec3(0.0, 0.0, -rotate_size);

	rayPos.xz = rotate2d(rayPos.xz, (iMouse.x/iResolution.x)*14.0);
	rayDir.xz = rotate2d(rayDir.xz, (iMouse.x/iResolution.x)*14.0);

    float size = 8.0;

    vec3 point = vec3(size, 0.0, 0.0);

    point.xy = rotate2d(point.xy, iTime);

    vec2 torris = vec2(size, 1.0);

    vec4 color = vec4(0.0, 0.0, 0.0, 0.0);

    for (int i = 0; i < MAX_STEPS; i++)
    {
        float step_size = torus(rayPos, torris);
        if (step_size < INTERSECT_SIZE)
        {
            // now march throught the toris
            for (int i = 0; i < MAX_STEPS; i++)
            {
                float torus_dist = isInsideTorus(rayPos, torris);
                if (!(torus_dist < torris.y + 0.1))
                    break;

                rayPos += rayDir * 0.1;

                float dist = distance(rayPos, point);

                float smoth = smoothstep(0.0, 8.0, dist);

                float transparency = (1.0 - smoth) * 0.03;

                vec4 atmospher_color = vec4(hsv2rgb(vec3(smoth, 0.5, 1.0)) + vec3(1.0, 1.0, 1.0) * 1.0, transparency);

                color = blendColors(color, atmospher_color);
            }
        }

        rayPos += rayDir * step_size;
    }


    // Output to screen
    fragColor = blendColors(vec4(0.129,0.145,0.173,0.5), color);
}
